using System;using System.Globalization;using Por.Core;
class StrUtilTests{public static void Main(){int n=0;for(int i=0;i<=65535;i++){string e=(i%100).ToString("D2",CultureInfo.InvariantCulture);if(StrUtil.ZeroPad2((ushort)i)!=e)throw new Exception("zero "+i);n++;}for(int w=0;w<256;w++){string s="abcdef";string cut=s.Substring(0,Math.Min(s.Length,w));if(StrUtil.PadRight(s,(byte)w)!=cut.PadRight(w)||StrUtil.PadLeft(s,(byte)w)!=cut.PadLeft(w))throw new Exception("pad "+w);n+=2;}foreach(int v in new[]{int.MinValue,-42,0,42,int.MaxValue}){if(StrUtil.NumStr(v)!=v.ToString(CultureInfo.InvariantCulture))throw new Exception("num");n++;}Console.WriteLine("StrUtil assertions passed: "+n);}}
